"use strict";(globalThis.webpackChunkgrc||=[]).push([[1551],{26120(e){e.exports=JSON.parse('{"citeKey":"kougkas2018hermes","slug":"kougkas-2018-hermes-25f4","title":"Hermes: A Heterogeneous-Aware Multi-Tiered Distributed I/O Buffering System","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The 27th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC), Tempe, AZ, USA, 2018. pp. 219-230","type":"Conference","entryType":"inproceedings","date":"June, 2018","year":2018,"era":"iit","month":6,"doi":"10.1145/3208040.3208059","abstract":"Modern High-Performance Computing (HPC) systems are adding extra layers to the memory and storage hierarchy, named deep memory and storage hierarchy (DMSH), to increase I/O perfor- mance. New hardware technologies, such as NVMe and SSD, have been introduced in burst buffer installations to reduce the pressure for external storage and boost the burstiness of modern I/O systems. The DMSH has demonstrated its strength and potential in practice. However, each layer of DMSH is an independent heterogeneous system and data movement among more layers is significantly more complex even without considering heterogeneity. How to efficiently utilize the DMSH is a subject of research facing the HPC community. In this paper, we present the design and implementa- tion of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system. Hermes enables, manages, su- pervises, and, in some sense, extends I/O buffering to fully integrate into the DMSH. We introduce three novel data placement policies to efficiently utilize all layers and we present three novel techniques to perform memory, metadata, and communication management in hierarchical buffering systems. Our evaluation shows that, in ad- dition to automatic data movement through the hierarchy, Hermes can significantly accelerate I/O and outperforms by more than 2x state-of-the-art buffering platforms.","hasAbstract":true,"lede":"We present the design and implementa- tion of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system.","links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-hermes-25f4.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-hermes-25f4-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hermes"],"memberAuthors":["kougkas-anthony","devarajan-hariharan","sun-xian-he"]}')}}]);